import {subtitleConvert} from '../extra-core.mjs';
export function wavPCM(channels,sampleRate){if(!channels.length||channels.length>2||!Number.isInteger(sampleRate)||sampleRate<8000||sampleRate>192000)throw Error('Use mono/stereo audio at a supported sample rate.');const frames=channels[0].length;if(!frames||channels.some(x=>x.length!==frames)||frames*channels.length>12000000)throw Error('Audio is empty or exceeds the 12-million-sample limit.');const buffer=new ArrayBuffer(44+frames*channels.length*2),v=new DataView(buffer),write=(at,s)=>{for(let i=0;i<s.length;i++)v.setUint8(at+i,s.charCodeAt(i));};write(0,'RIFF');v.setUint32(4,buffer.byteLength-8,true);write(8,'WAVE');write(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,channels.length,true);v.setUint32(24,sampleRate,true);v.setUint32(28,sampleRate*channels.length*2,true);v.setUint16(32,channels.length*2,true);v.setUint16(34,16,true);write(36,'data');v.setUint32(40,frames*channels.length*2,true);let p=44;for(let i=0;i<frames;i++)for(const channel of channels){const s=Math.max(-1,Math.min(1,channel[i]));v.setInt16(p,s<0?s*32768:s*32767,true);p+=2;}return buffer;}
export function shiftSubtitles(input,offset,clamp=false){if(!Number.isFinite(offset)||Math.abs(offset)>86400)throw Error('Use an offset within one day.');const target=/^\s*WEBVTT/.test(input)?'vtt':'srt',source=subtitleConvert(input,target);let clamped=0;const parse=s=>{const a=s.replace(',','.').split(':').map(Number);return a.length===3?a[0]*3600+a[1]*60+a[2]:a[0]*60+a[1];};const format=(seconds,sep)=>{const ms=Math.round(seconds*1000),h=Math.floor(ms/3600000),m=Math.floor(ms/60000)%60,s=Math.floor(ms/1000)%60;return [h,m,s].map(x=>String(x).padStart(2,'0')).join(':')+sep+String(ms%1000).padStart(3,'0');};const text=source.text.replace(/(\d{2,}:\d{2}:\d{2}[,.]\d{3})\s+-->\s+(\d{2,}:\d{2}:\d{2}[,.]\d{3})/g,(_,a,b)=>{let x=parse(a)+offset,y=parse(b)+offset;if(x<0||y<0){if(!clamp)throw Error('This offset moves a cue before zero. Choose clamp or a smaller negative shift.');clamped++;x=Math.max(0,x);y=Math.max(0,y);}return format(x,a.includes(',')?',':'.')+' --> '+format(y,b.includes(',')?',':'.');});return{text,count:source.count,clamped,format:target};}
